import plur from 'plur'
import {memo, Suspense, useMemo} from 'react'

import {restApi} from '../../../../../../../../services/rest'
import type {ProjectId} from '../../../../../../../../types'
import {UserProperties} from '../../../../../../../../utils/userProperties'
import ContentPanel from '../../../../../../../common/ContentPanel/ContentPanel'
import {useSequenceLoaderReadyHandler} from '../../../../../../../common/SequenceLoader/SequenceLoader.hooks'
import type {SeqProps} from '../../../../../../../common/SequenceLoader/SequenceLoader.types'
import {
  getProblemOccurrencesLocator,
  getRootNode,
} from '../../../../../../../packages/BuildProblems/BuildProblemsPreview/BuildProblemsPreview.utils'
import BuildProblemsTree from '../../../../../../../packages/BuildProblems/BuildProblemsTree/BuildProblemsTree.container'
import {buildProblemsTreeContextDefaultValue} from '../../../../../../../packages/BuildProblems/BuildProblemsTree/BuildProblemsTree.context'

type Props = {
  jobId: number
  projectId?: ProjectId
} & SeqProps

function JobProblemsTree({jobId, projectId}: Props) {
  const endpoint = buildProblemsTreeContextDefaultValue.getEndpoint()
  const locator = getProblemOccurrencesLocator(jobId)
  const {
    count = 0,
    newFailedCount = 0,
    isReady,
  } = restApi.endpoints.getProblemOccurrenceTree.useQueryState(
    {
      endpoint,
      locator,
      treeLocator: locator,
    },
    {
      selectFromResult: ({data}) => {
        const rootNode = getRootNode(data?.tree.node)
        return {
          count: rootNode?.count,
          newFailedCount: rootNode?.newFailedCount,
          isReady: data != null,
        }
      },
    },
  )
  useSequenceLoaderReadyHandler(isReady)

  const labelId = 'jobProblemsTree'
  const renderContent = useMemo(
    () => (
      <Suspense>
        <BuildProblemsTree
          labelId={labelId}
          key={locator}
          locator={locator}
          projectId={projectId}
          buildId={jobId}
          isSimple
        />
      </Suspense>
    ),
    [projectId, jobId, locator],
  )

  return isReady && count > 0 ? (
    <ContentPanel
      panelType={UserProperties.EXPAND_BUILD_PROBLEMS_SECTION}
      heading={
        count > 0 ? (
          <span id={labelId}>{`${count} Build ${plur('Problem', count)}${
            newFailedCount > 0 ? `, ${newFailedCount} new` : ''
          }`}</span>
        ) : (
          ''
        )
      }
      content={renderContent}
      withBorder={false}
    />
  ) : null
}

export default memo(JobProblemsTree)
