import plur from 'plur'
import {memo, useMemo} from 'react'
import {useLocation} from 'react-router'

import {getBuildLocator} from '../../../../../../../../rest/locators'
import {getHrefWithQueryParams} from '../../../../../../../../routes'
import {restApi} from '../../../../../../../../services/rest'
import type {ProjectId} from '../../../../../../../../types'
import {UserProperties} from '../../../../../../../../utils/userProperties'
import ContentPanel from '../../../../../../../common/ContentPanel/ContentPanel'
import {useSequenceLoaderReadyHandler} from '../../../../../../../common/SequenceLoader/SequenceLoader.hooks'
import type {SeqProps} from '../../../../../../../common/SequenceLoader/SequenceLoader.types'
import {getOwnTestsLocator} from '../../../../../../../packages/Tests/TestsPreviewPanel/TestsPreviewPanel.utils'
import type {TestsPreviewPanelCountersFragment$key} from '../../../../../../../packages/Tests/TestsPreviewPanel/TestsPreviewPanelCounters/__generated__/TestsPreviewPanelCountersFragment.graphql'
import TestsPreviewPanelCounters from '../../../../../../../packages/Tests/TestsPreviewPanel/TestsPreviewPanelCounters/TestsPreviewPanelCounters'
import TestsTree from '../../../../../../../packages/Tests/TestsTree/TestsTree'
import {useTestOccurrenceTreeArg} from '../../../../../../../packages/Tests/TestsTree/TestsTree.hooks'
import {
  getRootTestCounters,
  getTestsLocator as getTestTreeLocator,
} from '../../../../../../../packages/Tests/TestsTree/TestsTree.utils'

import styles from './JobTestsTree.module.css'

type Props = {
  jobId: number
  projectId?: ProjectId
  countsKey: TestsPreviewPanelCountersFragment$key | null
} & SeqProps

function JobTestsTree({jobId, projectId, countsKey}: Props) {
  const ownTestsLocator = getOwnTestsLocator(getBuildLocator(jobId))
  const locator = getTestTreeLocator({baseLocator: ownTestsLocator})
  const arg = useTestOccurrenceTreeArg(locator)
  const {count, newFailedCount, isReady} = restApi.endpoints.getTestOccurrenceTree.useQueryState(
    arg,
    {
      selectFromResult: ({data}) => ({
        count: getRootTestCounters(data?.tree.node)?.failed ?? 0,
        newFailedCount: getRootTestCounters(data?.tree.node)?.newFailed ?? 0,
        isReady: data != null,
      }),
    },
  )
  const location = useLocation()
  const testsTabLink = getHrefWithQueryParams(location, null, params => ({
    ...params,
    tab: 'testsInfo',
  }))

  useSequenceLoaderReadyHandler(isReady)

  const labelId = 'jobTestsTree'
  const renderContent = useMemo(
    () => (
      <>
        <TestsTree
          labelId={labelId}
          locator={locator}
          arg={arg}
          projectId={projectId}
          buildId={jobId}
          isSimple
        />
        <TestsPreviewPanelCounters
          className={styles.counters}
          countsKey={countsKey}
          testsTabLink={testsTabLink}
        />
      </>
    ),
    [locator, arg, projectId, jobId, countsKey, testsTabLink],
  )

  return isReady && count > 0 ? (
    <ContentPanel
      heading={
        count > 0 ? (
          <span id={labelId}>{`${count} Failed ${plur('Test', count)}${
            newFailedCount > 0 ? `, ${newFailedCount} new` : ''
          }`}</span>
        ) : (
          'Tests'
        )
      }
      panelType={UserProperties.EXPAND_BUILD_TESTS_SECTION}
      content={renderContent}
      withBorder={false}
    />
  ) : null
}

export default memo(JobTestsTree)
