import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import type {EntryPointProps} from 'react-relay'

import type {BuildId, ProjectId} from '../../../../../../../types'
import SequenceLoader from '../../../../../../common/SequenceLoader/SequenceLoader'
import {useFetchBuildTestCounters} from '../../../../../../packages/Tests/Tests.hooks'
import {getCountsVariables} from '../../../../../../packages/Tests/TestsPreviewPanel/TestsPreviewPanel.queries'

import JobProblemsTree from './JobProblemsTree/JobProblemsTree'
import type {JobTestsTreeCountsQuery} from './JobTestsTree/__generated__/JobTestsTreeCountsQuery.graphql'
import JobTestsTree from './JobTestsTree/JobTestsTree'
import {jobTestsTreeCountsQuery} from './JobTestsTree/JobTestsTree.queries'

type Props = {
  jobId: BuildId
  projectId?: ProjectId
  buildLocator?: string
}

type Queries = {
  testCounts: JobTestsTreeCountsQuery
}

function OverviewTab({
  queries,
  props: {jobId, projectId, buildLocator},
}: EntryPointProps<Queries, {}, Props, {}>) {
  const {testOccurrences} = useFetchBuildTestCounters(
    jobId,
    buildLocator,
    jobTestsTreeCountsQuery,
    queries.testCounts,
    getCountsVariables,
  )
  return (
    <SequenceLoader
      loader={
        <div>
          <LoaderInline>{'Loading...'}</LoaderInline>
        </div>
      }
    >
      <JobProblemsTree jobId={jobId} projectId={projectId} seqKey="JobProblemsTree" />
      <JobTestsTree
        jobId={jobId}
        seqKey="JobTestsTree"
        countsKey={testOccurrences?.testCounters ?? null}
        projectId={projectId}
      />
    </SequenceLoader>
  )
}
export default OverviewTab
export type OverviewTabComponent = typeof OverviewTab
